  (27338, 'पंचवार्षिक योजना', 'Economy', 'MPSC Practice Subject Test', 2024, '१९५१ ते २०१७ दरम्यान भारतात एकूण किती पंचवार्षिक योजना राबवल्या गेल्या?', '{"A": "१०", "B": "११", "C": "१२", "D": "१५"}'::jsonb, 'C', '१९५१–२०१७ दरम्यान एकूण १२ पंचवार्षिक योजना. १२वी (२०१२–१७) शेवटची.', '{"Economy","MPSC Practice Subject Test","2024","पंचवार्षिक योजना"}'::text[], 'Medium'),
  (27339, 'पंचवार्षिक योजना', 'Economy', 'MPSC Practice Subject Test', 2024, 'सरकती / Rolling Plan कोणत्या कालावधीत लागू होती?', '{"A": "१९७४–७८", "B": "१९७८–८०", "C": "१९८०–८५", "D": "१९६६–६९"}'::jsonb, 'B', '१९७८–८० मध्ये Rolling Plan (सरकती योजना).', '{"Economy","MPSC Practice Subject Test","2024","पंचवार्षिक योजना"}'::text[], 'Medium'),
  (27340, 'पंचवार्षिक योजना', 'Economy', 'MPSC Practice Subject Test', 2024, 'राजकीय अस्थिरतेमुळे वार्षिक योजना कोणत्या दोन कालावधीत आल्या?', '{"A": "१९५१–५६ व १९५६–६१", "B": "१९६६–६९ व १९७४–७८", "C": "१९७८–८० व १९९०–९२", "D": "१९८५–९० व १९९२–९७"}'::jsonb, 'C', '१९७८–८० आणि १९९०–९२ हे दोन अस्थिरतेचे वार्षिक-योजना काळ.', '{"Economy","MPSC Practice Subject Test","2024","पंचवार्षिक योजना"}'::text[], 'Medium'),
