  (27344, 'पंचवार्षिक योजना', 'Economy', 'MPSC Practice Subject Test', 2024, 'ग्रामीण वेतन-रोजगार योजनांची योग्य उत्क्रांती कोणती?', '{"A": "IRDP → NREP → MGNREGA", "B": "NREP → RLEGP → JRY → SGRY → NREGA/MGNREGS", "C": "TRYSEM → IRDP → NREGA", "D": "DPAP → RRB → NREGA"}'::jsonb, 'B', 'NREP (१९८०) → RLEGP (१९८३) → JRY (१९८९) → SGRY (२००१) → NREGA (२००५) → MGNREGS (२००९).', '{"Economy","MPSC Practice Subject Test","2024","पंचवार्षिक योजना"}'::text[], 'Medium'),
  (27345, 'पंचवार्षिक योजना', 'Economy', 'MPSC Practice Subject Test', 2024, 'पहिल्या पंचवार्षिक योजनेला कोणते नाव/ओळख दिली जाते?', '{"A": "शिक्षण योजना", "B": "भौतिकवादी योजना", "C": "पुनरुत्थान योजना", "D": "स्वावलंबन योजना"}'::jsonb, 'C', 'पुनरुत्थान योजना — अर्थव्यवस्था पुन्हा उभी करणे.', '{"Economy","MPSC Practice Subject Test","2024","पंचवार्षिक योजना"}'::text[], 'Medium'),
  (27346, 'पंचवार्षिक योजना', 'Economy', 'MPSC Practice Subject Test', 2024, 'रेल्वे इंजिन कारखाना चित्तरंजन व रेल्वे डबे कारखाना अनुक्रमे कोठे?', '{"A": "गुजरात व राजस्थान", "B": "पुणे व नाशिक", "C": "पश्चिम बंगाल व तमिळनाडू (पेरांबुर)", "D": "बिहार व ओडिशा"}'::jsonb, 'C', 'इंजिन — चित्तरंजन; डबे — पेरांबुर (तमिळनाडू).', '{"Economy","MPSC Practice Subject Test","2024","पंचवार्षिक योजना"}'::text[], 'Medium'),
  (27347, 'पंचवार्षिक योजना', 'Economy', 'MPSC Practice Subject Test', 2024, 'दामोदर खोरे प्रकल्प कोणाच्या शिफारशीनुसार व कोणत्या मॉडेलवर?', '{"A": "नेहरू — व्हॉल्टा", "B": "मेघनाद साहा — टेनेसी व्हॅली", "C": "गाडगीळ — डॅन्यूब", "D": "स्वामीनाथन — नील"}'::jsonb, 'B', 'मेघनाद साहा शिफारस; टेनेसी व्हॅली (TVA) मॉडेल.', '{"Economy","MPSC Practice Subject Test","2024","पंचवार्षिक योजना"}'::text[], 'Medium'),
  (27348, 'पंचवार्षिक योजना', 'Economy', 'MPSC Practice Subject Test', 2024, 'Hindu Rate of Growth ही संकल्पना कोणाची?', '{"A": "मनमोहन सिंह", "B": "अमर्त्य सेन", "C": "राजकृष्ण", "D": "महालनोबीस"}'::jsonb, 'C', 'राजकृष्ण — १९५०–८० च्या सुमारे ३.५% वाढीला Hindu Rate of Growth.', '{"Economy","MPSC Practice Subject Test","2024","पंचवार्षिक योजना"}'::text[], 'Medium'),
  (27349, 'पंचवार्षिक योजना', 'Economy', 'MPSC Practice Subject Test', 2024, 'दुसऱ्या योजनेतील लोहपोलाद — योग्य जोडी कोणती?', '{"A": "भिलाई–ब्रिटन; दुर्गापूर–रशिया; रुरकेला–जर्मनी", "B": "दुर्गापूर–ब्रिटन; भिलाई–रशिया; रुरकेला–जर्मनी", "C": "रुरकेला–ब्रिटन; भिलाई–जर्मनी; दुर्गापूर–रशिया", "D": "सर्व रशिया"}'::jsonb, 'B', 'दुर्गापूर–ब्रिटन; भिलाई–रशिया; रुरकेला–जर्मनी.', '{"Economy","MPSC Practice Subject Test","2024","पंचवार्षिक योजना"}'::text[], 'Medium'),
  (27350, 'पंचवार्षिक योजना', 'Economy', 'MPSC Practice Subject Test', 2024, 'पहिल्या योजनेबाबत खालीलपैकी कोणते विधान बरोबर?', '{"A": "चलनवाढ प्रचंड वाढली", "B": "चलनवाढ निर्देशांक सुमारे १३% नी कमी झाला", "C": "शेती पूर्णपणे दुर्लक्षित", "D": "साध्य दर अपेक्षितपेक्षा कमी"}'::jsonb, 'B', 'चलनवाढ निर्देशांक सुमारे १३% नी कमी — या योजनेचे वैशिष्ट्य.', '{"Economy","MPSC Practice Subject Test","2024","पंचवार्षिक योजना"}'::text[], 'Medium')
